"""Compactor — merges small Parquet files generated by streaming sinks.

Streaming upserts create many small files over time.  The :class:`Compactor`
reads all files for a table, sorts by clustering columns, and rewrites them
into fewer files — entirely inside DuckDB without any Python-side data
movement.

Contract (#189)
---------------
* It reads the layout :class:`~sqldim.sinks.ParquetSink` writes: every
  column, partition columns included, is read from the files with the type
  written (``hive_partitioning=false``), never from directory names.
* It writes the same layout: partition columns stay inside the files
  (``WRITE_PARTITION_COLUMNS``), so a BOOLEAN ``is_current`` stays BOOLEAN.
* It never overwrites a file already written: the new files go to a staging
  directory, which replaces the table's directory only after the row count
  is checked and no file was appended meanwhile.  This needs a local
  filesystem; on a remote URI it raises
  :class:`~sqldim.sinks.SinkUnsupported` before anything is written.
* A file that lacks a partition column (written by the sink before #178)
  raises :class:`ParquetLayoutError`; migrate it once with
  :func:`~sqldim.io.migrate_legacy_parquet`.

Usage
-----
.. code-block:: python

    import duckdb
    from sqldim.io import Compactor

    con = duckdb.connect()
    Compactor.compact(
        con=con,
        path="/data/warehouse/events",
        partition_by=["ingest_date"],
        zorder_by=["source", "customer_id"],
    )
"""

from __future__ import annotations

from collections.abc import Mapping

import duckdb

from sqldim.io._parquet_files import (
    ParquetLayoutError,
    file_list,
    lit,
    local_dir,
    partition_options,
    replace_table,
    table_files,
)
from sqldim.sinks._errors import SinkUnsupported

__all__ = ["Compactor", "ParquetLayoutError"]


def _order_clause(zorder_by: list[str] | None) -> str:
    if not zorder_by:
        return ""
    return " ORDER BY " + ", ".join(zorder_by)


def _require_columns(files: Mapping[str, set[str]], columns: list[str]) -> None:
    for name, cols in sorted(files.items()):
        missing = [c for c in columns if c not in cols]
        if missing:
            raise ParquetLayoutError(
                f"{name!r} has no column {missing}: it was written before "
                "partition columns were stored in the files (#178); migrate the "
                "table once with sqldim.io.migrate_legacy_parquet"
            )


def _target_options(
    partition_by: list[str] | None, target_file_size_mb: int | None
) -> tuple[str, bool]:
    """The COPY options, and whether the target is a directory."""
    if partition_by:
        if target_file_size_mb is not None:
            raise SinkUnsupported(
                "Compactor: DuckDB cannot combine FILE_SIZE_BYTES with "
                "PARTITION_BY; pass target_file_size_mb=None to compact a "
                "partitioned table"
            )
        return partition_options(partition_by), True
    if target_file_size_mb is not None:
        if not isinstance(target_file_size_mb, int) or target_file_size_mb <= 0:
            raise ValueError(
                f"target_file_size_mb must be > 0, got {target_file_size_mb!r}"
            )
        return f", FILE_SIZE_BYTES '{target_file_size_mb}MB'", True
    return "", False


class Compactor:
    """Merges the small Parquet files of a table; see the module docstring."""

    @staticmethod
    def compact(
        con: duckdb.DuckDBPyConnection,
        path: str,
        *,
        partition_by: list[str] | None = None,
        zorder_by: list[str] | None = None,
        target_file_size_mb: int | None = None,
    ) -> int:
        """Read, sort and rewrite all Parquet files under *path*.

        Parameters
        ----------
        con:
            DuckDB connection.
        path:
            Local root directory of the Parquet table.
        partition_by:
            Hive partition columns of the rewrite.  Each must be stored in
            every file, as :class:`~sqldim.sinks.ParquetSink` writes them.
            ``None`` writes the rows unpartitioned.
        zorder_by:
            Columns to sort by before writing (Z-ORDER approximation via
            ``ORDER BY``).  ``None`` skips sorting.
        target_file_size_mb:
            Rotate output files at this size (``FILE_SIZE_BYTES``).  DuckDB
            supports it only for an unpartitioned rewrite; together with
            *partition_by* it raises :class:`~sqldim.sinks.SinkUnsupported`.
            ``None`` (default) writes one file per partition and thread.

        Returns
        -------
        int
            Number of rows written, equal to the number read.
        """
        root = local_dir(path, "Compactor.compact")
        options, to_dir = _target_options(partition_by, target_file_size_mb)
        files = table_files(con, root)
        _require_columns(files, list(partition_by or ()))
        source = f"read_parquet({file_list(sorted(files))}, hive_partitioning=false)"
        select = f"SELECT * FROM {source}{_order_clause(zorder_by)}"

        def write(stage: str) -> None:
            out = stage if to_dir else f"{stage}/data_0.parquet"
            con.execute(f"COPY ({select}) TO {lit(out)} (FORMAT parquet{options})")

        return replace_table(con, root, sorted(files), source, write)
